export function translateString(s: string, lang: Locale): string | null {
  if (lang === 'en') return s;
  const isFr = lang === 'fr';
  const dict = isFr ? DICTIONARY_FR : DICTIONARY_ES;
  const normDict = isFr ? NORM_FR : NORM_ES;
  const patterns = isFr ? PATTERNS_FR : PATTERNS_ES;
  const dateFn = isFr ? datesFr : datesEs;

  const k = String(s).replace(/\s+/g, ' ').trim();
  if (!k) return null;
  if (dict[k]) return dict[k];
  const kn = k.replace(/[\u2018\u2019]/g, "'").replace(/[\u201c\u201d]/g, '"');
  if (normDict[kn]) return normDict[kn];

  for (let i = 0; i < patterns.length; i++) {
    const [regex, replacer] = patterns[i];
    if (regex.test(k)) {
      if (typeof replacer === 'string') {
        return k.replace(regex, replacer);
      } else {
        return k.replace(regex, replacer);
      }
    }
  }

  if (/\b(January|February|March|April|May|June|July|August|September|October|November|December|Monday|Tuesday|Wednesday|Thursday|Friday|Saturday|Sunday)\b/.test(k) && k.length < 80) {
    return dateFn(k);
  }

  return null;
}

export function tStr(s: string, lang: Locale = 'en'): string {
  if (!s || lang === 'en') return s;
  return translateString(s, lang) || s;
}

const ORIG = new WeakMap<Node, { en: string; es?: string | null; fr?: string | null }>();
const ORIGA = new WeakMap<Element, Record<string, { en: string; es?: string | null; fr?: string | null }>>();
let busy = false;
let queued = false;
const ATTRS = ['placeholder', 'aria-label', 'title'];

function skip(el: Element | null): boolean {
  if (!el) return true;
  return !!(el.closest && el.closest('script,style,textarea,input,pre,code,[contenteditable],[data-i18n-skip]'));
}

function skipAttr(el: Element | null): boolean {
  if (!el) return true;
  return !!(el.closest && el.closest('script,style,pre,code,[contenteditable],[data-i18n-skip]'));
}

function pad(cur: string, t: string): string {
  const leading = cur.match(/^\s*/)?.[0] || '';
  const trailing = cur.match(/\s*$/)?.[0] || '';
  return leading + t + trailing;
}

export function applyTranslations(root?: Element | Document, currentLang?: Locale) {
  if (typeof window === 'undefined') return;

  const lg: Locale = currentLang || ((localStorage.getItem('site_language') as Locale) || (localStorage.getItem('tm_lang') as Locale) || 'en');
  busy = true;

  try {
    const targetRoot = (root || document.body) as Node;
    if (!targetRoot) return;

    const walker = document.createTreeWalker(targetRoot, NodeFilter.SHOW_TEXT, null);
    let n: Node | null;
    while ((n = walker.nextNode())) {
      if (skip(n.parentElement)) continue;
      const cur = n.nodeValue;
      if (!cur || !/[A-Za-z]/.test(cur)) continue;

      let o = ORIG.get(n);
      if (o && cur !== o.en && cur !== o.fr && cur !== o.es) {
        o = undefined;
      }
      if (!o) {
        o = { en: cur };
        ORIG.set(n, o);
      }

      if (lg !== 'en' && !(lg in o)) {
        const t = translateString(o.en, lg);
        o[lg] = t ? pad(o.en, t) : null;
      }

      const want = lg !== 'en' && o[lg] ? o[lg] : o.en;
      if (want && cur !== want) {
        n.nodeValue = want;
      }
    }

    const els = ((root || document.body) as Element).querySelectorAll('[placeholder],[aria-label],[title]');
    for (let i = 0; i < els.length; i++) {
      const el = els[i];
      if (skipAttr(el)) continue;
      let m = ORIGA.get(el);
      if (!m) {
        m = {};
        ORIGA.set(el, m);
      }
      for (const a of ATTRS) {
        const v = el.getAttribute(a);
        if (v == null) continue;
        if (!m[a] || (v !== m[a].en && v !== m[a].fr && v !== m[a].es)) {
          m[a] = { en: v };
        }
        if (lg !== 'en' && !(lg in m[a])) {
          m[a][lg] = translateString(m[a].en, lg);
        }
        const want = lg !== 'en' && m[a][lg] ? m[a][lg] : m[a].en;
        if (want && v !== want) {
          el.setAttribute(a, want);
        }
      }
    }

    document.documentElement.lang = lg;
  } catch (err) {
    console.error('Translation error:', err);
  } finally {
    busy = false;
  }
}

export function scheduleTranslation(lang?: Locale) {
  if (typeof window === 'undefined') return;
  if (queued) return;
  queued = true;
  requestAnimationFrame(() => {
    queued = false;
    applyTranslations(undefined, lang);
  });
}

export function initI18nObserver() {
  if (typeof window === 'undefined' || (window as any).__tm_i18n_initialized) return;
  (window as any).__tm_i18n_initialized = true;

  if (document.body) {
    applyTranslations();
  }

  const observer = new MutationObserver(() => {
    if (!busy) scheduleTranslation();
  });

  if (document.body) {
    observer.observe(document.body, {
      childList: true,
      subtree: true,
      characterData: true,
      attributes: true,
      attributeFilter: ATTRS,
    });
  }
}
